<script lang="ts">
 import {untrack} from 'svelte';
 import {setWorkspacePage,workspace} from './store.svelte';
 $effect(()=>{const path=page.url.pathname,identity=demo.user?.id,role=demo.user?.role;untrack(()=>setWorkspacePage(path));});
 $effect(()=>{if(page.url.pathname.replace(/\/$/,'')==='/templates/overrides'&&demo.user?.role==='admin')void goto('/subscription-generator',{replaceState:true});});
 $effect(()=>{if(page.url.pathname.replace(/\/$/,'')==='/reality-targets'&&demo.user?.role==='admin')void goto('/servers?tab=inbounds',{replaceState:true});});
 $effect(()=>{if(['/outbounds','/routing'].includes(page.url.pathname)&&demo.user?.role==='admin'){const tab=page.url.pathname==='/routing'?'routing':'outbounds';const row=(demo.data.outbounds??[]).find(row=>row.id===page.url.searchParams.get('detail'));const id=page.url.searchParams.get('server')||row?.serverId||'';const scope=page.url.searchParams.get('inbound')??'';void goto(`/servers?tab=${tab}${id?'&xray='+encodeURIComponent(id):''}${scope?'&routingScope='+encodeURIComponent(scope):''}`,{replaceState:true});}});
 $effect(()=>{if(page.url.pathname==='/inbounds'&&demo.user?.role==='admin'){const id=page.url.searchParams.get('detail')??'';void goto(`/servers?tab=inbounds${id?'&inbound='+encodeURIComponent(id):''}`,{replaceState:true});}});

 import GlassTheme from './components/GlassTheme.svelte';
 import LazyPage from './components/LazyPage.svelte';
 import TemporarySubscriptions from './components/TemporarySubscriptions.svelte';
 import Limits from './pages/Limits.svelte';
 import EntryLanding from './components/EntryLanding.svelte';import QRApproval from './components/QRApproval.svelte';import CustomAppearance from './components/CustomAppearance.svelte';import CallbackLogin from './components/CallbackLogin.svelte';import MemberServices from './components/MemberServices.svelte';import {startCallbackLogin} from './callback-login';import {onMount} from 'svelte';import {page} from '$app/state';import {goto} from '$app/navigation';import Icon from './components/Icon.svelte';import Modal from './components/Modal.svelte';import {groups,extra,navigation,canAccessPage} from './navigation';import {demo,loadDemo,logout,stopRefresh} from './store.svelte';import Dashboard from './pages/Dashboard.svelte';import EntityPage from './components/EntityPage.svelte';import {modules} from './modules';import Subscriptions from './pages/Subscriptions.svelte';import Plans from './pages/Plans.svelte';import Carpools from './pages/Carpools.svelte';import Traffic from './pages/Traffic.svelte';import Portal from './pages/Portal.svelte';import Probe from './pages/Probe.svelte';import AuthGate from './components/AuthGate.svelte';import IdentitySecurity from './components/IdentitySecurity.svelte';
 let searchOpen=$state(false),search=$state(''),mobile=$state(false);const current=$derived(navigation.find(n=>n[0]===page.url.pathname)?.[1]??'总览');const allowed=(path:string)=>canAccessPage(demo.user?.role,path);const filtered=$derived(navigation.filter(n=>allowed(n[0])&&n[1].includes(search)));
 onMount(()=>{loadDemo();const media=window.matchMedia('(max-width: 767px)');mobile=media.matches;if(mobile)demo.sidebar=false;const resize=()=>{mobile=media.matches;};media.addEventListener('change',resize);const listener=(e:KeyboardEvent)=>{if((e.ctrlKey||e.metaKey)&&e.key==='k'){e.preventDefault();searchOpen=true;}if((e.ctrlKey||e.metaKey)&&e.key==='b'){e.preventDefault();demo.sidebar=!demo.sidebar;}};window.addEventListener('keydown',listener);return()=>{window.removeEventListener('keydown',listener);stopRefresh();media.removeEventListener('change',resize);};});
</script>
{#if !demo.connecting&&!demo.hiddenEntry&&!page.url.pathname.startsWith('/entrance')}<CustomAppearance css={demo.user?demo.settings.customCSS:undefined}/>{/if}<svelte:head><title>{demo.hiddenEntry?'404':demo.connecting?'正在打开页面':current+' · ASWired'}</title><meta name="description" content="ASWired · Xray 服务器管理与订阅工作区"/></svelte:head>
{#if page.url.pathname.startsWith('/entrance/')}<EntryLanding/>{:else if demo.hiddenEntry&&page.url.pathname!=='/probe'}<div class="empty" style="min-height:100dvh;justify-content:center"><h1>404</h1><p>页面不存在</p></div>{:else if page.url.pathname==='/auth/qr'&&demo.user}<QRApproval/>{:else if page.url.pathname==='/auth/callback'||(page.url.pathname==='/auth/authorize'&&demo.user)}<CallbackLogin/>{:else if !demo.user&&page.url.pathname==='/probe'}<div class="public-probe"><div class="section-head"><a class="brand" href="/probe"><img class="brand-mark" src="/aswired-logo.gif" alt="" width="100" height="90"/><strong>ASWired</strong></a><button class="button" onclick={()=>startCallbackLogin(location.origin)}>登录工作区</button></div><Probe/></div>{:else if !demo.user&&demo.connecting}<div class="empty" style="min-height:100dvh;justify-content:center">正在打开页面…</div>{:else if !demo.user}<AuthGate/>{:else}
<div class:collapsed={!demo.sidebar} class="app-shell">
 {#if demo.sidebar}<button class="sidebar-backdrop" aria-label="关闭导航" onclick={()=>demo.sidebar=false}></button>{/if}
 <aside class="sidebar" inert={mobile&&!demo.sidebar}><a href="/" class="brand" aria-label="ASWired 首页"><img class="brand-mark" src="/aswired-logo.gif" alt="" width="100" height="90"/><span><strong>ASWired</strong></span></a><div class="sidebar-scroll">{#each groups.filter(group=>group.items.some(item=>allowed(item[0]))) as group}<div class="nav-group"><div class="nav-label">{group.name}</div>{#each group.items.filter(item=>allowed(item[0])) as item}<a href={item[0]} onclick={()=>{if(window.matchMedia('(max-width: 767px)').matches)demo.sidebar=false;}} title={item[1]} class:active={page.url.pathname===item[0]}><Icon name={item[2]}/><span>{item[1]}</span>{#if item[0]==='/tasks'}<small>{workspace.pendingTasks}</small>{/if}</a>{/each}</div>{/each}</div><div class="sidebar-footer">{#each extra.filter(item=>allowed(item[0])) as item}<a href={item[0]} onclick={()=>{if(window.matchMedia('(max-width: 767px)').matches)demo.sidebar=false;}} title={item[1]} class:active={page.url.pathname===item[0]}><Icon name={item[2]}/><span>{item[1]}</span></a>{/each}</div></aside>
 <div class="workspace"><header class="topbar"><div class="topbar-title"><button class="icon-button" aria-label="切换侧栏" onclick={()=>demo.sidebar=!demo.sidebar}><Icon name="panel" size={15}/></button><span>{current}</span></div><div class="topbar-actions"><GlassTheme/><span class="demo-badge">{demo.role}</span><button aria-label="搜索页面" class="header-search" onclick={()=>searchOpen=true}><Icon name="search" size={14}/><span>搜索页面</span><kbd>Ctrl K</kbd></button>{#if allowed('/notifications')}<a class="icon-button" href="/notifications" aria-label="通知中心"><Icon name="bell" size={15}/></a>{/if}<span class="user-avatar" title={demo.user.username}>{demo.user.username.slice(0,1).toUpperCase()}</span><button class="button small" onclick={logout}>退出</button></div></header><main>{#if demo.connectionError}<div class="status-banner" role="alert">{demo.connectionError} · 页面保留上次读取的状态</div>{/if}{#key page.url.pathname}{#if !allowed(page.url.pathname)}<div class="card empty"><h1>没有访问权限</h1><p>此页面仅管理员可用。</p><a class="button" href="/portal">返回我的订阅</a></div>{:else if page.url.pathname === '/'}{#if demo.user.role==='admin'}<Dashboard/>{:else}<Portal/>{/if}{:else if page.url.pathname === '/billing'}<Plans/>{:else if page.url.pathname === '/nodes'}<LazyPage loader={()=>import('./pages/Nodes.svelte')}/>{:else if page.url.pathname === '/audit'}<LazyPage loader={()=>import('./pages/Logs.svelte')}/>{:else if page.url.pathname === '/inbounds'}<div class="empty">入站管理已移至服务器的 Xray 配置窗口。<a href="/servers" class="button">前往服务器</a></div>{:else if ['/outbounds','/routing'].includes(page.url.pathname)}<div class="empty">请在服务器的 Xray 配置窗口中管理出站与路由。<a href="/servers" class="button">前往服务器</a></div>{:else if page.url.pathname === '/certificates'}<LazyPage loader={()=>import('./pages/Certificates.svelte')}/>{:else if page.url.pathname === '/members'}<LazyPage loader={()=>import('./pages/Members.svelte')}/>{:else if modules[page.url.pathname.slice(1)]}<EntityPage collection={page.url.pathname.slice(1)}/>{:else if page.url.pathname === '/subscription-generator'}<LazyPage loader={()=>import('./pages/SubscriptionGenerator.svelte')}/>{:else if page.url.pathname === '/subscriptions'}<Subscriptions/>{:else if page.url.pathname === '/plans'}<Plans/>{:else if page.url.pathname === '/carpools'}<Plans/>{:else if page.url.pathname === '/templates'}<LazyPage loader={()=>import('./pages/Templates.svelte')}/>{:else if page.url.pathname === '/temporary-subscriptions'}<div class="page-head"><div><div class="eyebrow">订阅 / 限时分享</div><h1>临时订阅</h1><p>限制单节点配置链接的有效期与下载次数。</p></div></div><TemporarySubscriptions presetNodeId={page.url.searchParams.get('node')??''}/>{:else if page.url.pathname === '/reality-targets'}<div class="empty"><a href="/servers?tab=inbounds" class="button">前往服务器</a></div>{:else if page.url.pathname === '/limits'}<Limits/>{:else if page.url.pathname === '/traffic'}<Traffic/>{:else if page.url.pathname === '/join'}<div class="page-head"><div><h1>加入套餐</h1><p>使用管理员提供的邀请码领取套餐。</p></div></div><MemberServices/>{:else if page.url.pathname === '/portal'}<Portal/>{:else if page.url.pathname === '/probe'}<Probe/>{:else if page.url.pathname === '/account'}<div class="page-head"><div><div class="eyebrow">我的账户</div><h1>账户安全</h1><p>管理你的登录方式与访问凭据。</p></div></div><section class="card padded"><IdentitySecurity/></section>{:else if page.url.pathname === '/komari'}<LazyPage loader={()=>import('./pages/Komari.svelte')}/>{:else if page.url.pathname === '/settings'}<LazyPage loader={()=>import('./pages/Settings.svelte')}/>{:else if page.url.pathname === '/extensions'}<LazyPage loader={()=>import('./pages/Extensions.svelte')}/>{:else}<div class="empty"><h1>页面不存在</h1><a href="/" class="button">返回总览</a></div>{/if}{/key}</main><footer><span>ASWired <span class="muted">/</span> 所有连接，尽在掌握。</span><span>主控 {demo.version} · {demo.user.username}</span></footer></div>
 {#if demo.toast}<div class="toast" role="status"><Icon name="check"/>{demo.toast}</div>{/if}
 <Modal bind:open={searchOpen} title="搜索工作区" description="快速前往一个页面"><div class="search-input"><Icon name="search"/><input aria-label="搜索页面" bind:value={search} placeholder="服务器、订阅、拼车…"/></div><div class="command-results">{#each filtered as item}<button onclick={()=>{goto(item[0]);searchOpen=false;search='';}}><Icon name={item[2]}/>{item[1]}<Icon name="right" size={14}/></button>{:else}<div class="empty">未找到匹配页面</div>{/each}</div></Modal>
</div>

{/if}

